function animate(env,el,p){
    function R(num){ if(num<=0||num>=4000) return ""+num; var k=[[1000,"M"],[900,"CM"],[500,"D"],[400,"CD"],[100,"C"],[90,"XC"],[50,"L"],[40,"XL"],[10,"X"],[9,"IX"],[5,"V"],[4,"IV"],[1,"I"]], r=""; for(var i=0;i<k.length;i++){ while(num>=k[i][0]){ r+=k[i][1]; num-=k[i][0]; } } return r; }
    el.text=el.text.replace(/\d+/g, function(s){ return R(parseInt(s,10)); }); return el;
}
